const {execSync} = require('child_process');

const AGENTS_DIR = '/Users/kemuniagent/.openclaw/agents';
const STATE_KEY = 'model_switch_state';

const staticData = $getWorkflowStaticData('global');
if (!staticData[STATE_KEY]) staticData[STATE_KEY] = {};
const state = staticData[STATE_KEY];

// List agent dirs
let agentDirs = [];
try {
  const out = execSync(`ls "${AGENTS_DIR}" 2>/dev/null`, { encoding: 'utf8' });
  agentDirs = out.trim().split('\n').filter(Boolean);
} catch(e) { return [{ json: { agent: '', switches: 0, message: 'No agents dir' } }]; }

const allSwitches = [];

for (const agent of agentDirs) {
  const sessionsDir = `${AGENTS_DIR}/${agent}/sessions`;
  let files = [];
  try {
    const out = execSync(`ls "${sessionsDir}"/*.jsonl 2>/dev/null`, { encoding: 'utf8' });
    files = out.trim().split('\n').filter(f => f.endsWith('.jsonl'));
  } catch(e) { continue; }

  const events = [];
  for (const file of files) {
    let content = '';
    try { content = execSync(`cat "${file}" 2>/dev/null`, { encoding: 'utf8', maxBuffer: 5*1024*1024 }); } catch(e) { continue; }
    for (const line of content.split('\n')) {
      if (!line.trim()) continue;
      try {
        const d = JSON.parse(line);
        if (d.type === 'model_change' && d.timestamp && d.provider && d.modelId) {
          events.push({ ts: d.timestamp, model: d.provider + '/' + d.modelId });
        }
      } catch(e) {}
    }
  }
  if (!events.length) continue;
  events.sort((a, b) => a.ts.localeCompare(b.ts));
  const lastSeen = state[agent] || '';
  const knownEvents = events.filter(e => e.ts <= lastSeen);
  const newEvents = events.filter(e => e.ts > lastSeen);
  if (!newEvents.length) continue;
  let prevModel = knownEvents.length ? knownEvents[knownEvents.length - 1].model : null;
  for (const ev of newEvents) {
    if (prevModel && prevModel !== ev.model) {
      allSwitches.push({ agent, from_model: prevModel, to_model: ev.model, timestamp: ev.ts, ts_fmt: new Date(ev.ts).toUTCString() });
    }
    prevModel = ev.model;
    if (!state[agent] || state[agent] < ev.ts) state[agent] = ev.ts;
  }
}

staticData[STATE_KEY] = state;

if (!allSwitches.length) {
  return [{ json: { agent: '', switches: 0, message: 'No new model switches' } }];
}
return allSwitches.map(s => ({ json: s }));
